// Minimal Chart.js shim - replace with real chart.umd.min.js for full Chart.js support
// See wwwroot/README.txt for instructions
(function(global){
  function Chart(ctx, config){
    this.ctx = typeof ctx === 'string' ? document.getElementById(ctx) : ctx;
    this.config = config;
    if(this.ctx) this._render();
  }
  Chart.prototype._render = function(){
    var cfg = this.config, data = cfg.data, canvas = this.ctx;
    if(!canvas) return;
    var w = canvas.width || canvas.offsetWidth || 400;
    var h = canvas.height || canvas.offsetHeight || 200;
    canvas.width = w; canvas.height = h;
    var ctx2d = canvas.getContext('2d');
    if(!ctx2d) return;
    ctx2d.fillStyle = '#fff';
    ctx2d.fillRect(0,0,w,h);
    if(!data || !data.datasets || !data.datasets[0]) return;
    var vals = data.datasets[0].data || [];
    var labels = data.labels || vals.map(function(_,i){ return 'Q'+(i+1); });
    var max = Math.max.apply(null, vals.map(function(v){ return +v||0; })) || 5;
    var pad = {l:40,r:10,t:20,b:40};
    var bw = (w - pad.l - pad.r) / (vals.length || 1);
    var colors = Array.isArray(data.datasets[0].backgroundColor)
      ? data.datasets[0].backgroundColor
      : [data.datasets[0].backgroundColor || '#1e3a5f'];
    vals.forEach(function(v,i){
      var bh = ((+v||0)/max) * (h - pad.t - pad.b);
      var x = pad.l + i*bw + bw*0.1;
      var y = h - pad.b - bh;
      ctx2d.fillStyle = colors[i % colors.length] || '#1e3a5f';
      ctx2d.fillRect(x, y, bw*0.8, bh);
      // label
      ctx2d.fillStyle = '#666';
      ctx2d.font = '9px sans-serif';
      ctx2d.textAlign = 'center';
      var lbl = String(labels[i] || '').substring(0,6);
      ctx2d.fillText(lbl, x+bw*0.4, h-pad.b+12);
      // value
      ctx2d.fillStyle = '#333';
      ctx2d.fillText((+v||0).toFixed(1), x+bw*0.4, y-4);
    });
    // y-axis
    ctx2d.strokeStyle = '#ccc';
    ctx2d.beginPath();
    ctx2d.moveTo(pad.l, pad.t);
    ctx2d.lineTo(pad.l, h-pad.b);
    ctx2d.lineTo(w-pad.r, h-pad.b);
    ctx2d.stroke();
  };
  Chart.prototype.update = function(){};
  Chart.prototype.destroy = function(){};
  Chart.register = function(){};
  global.Chart = Chart;
})(typeof window !== 'undefined' ? window : this);
